<?php
/**
 * MAW Starter CLI. Keeps generated files in sync with blueprints/blocks/*.yaml (the source of truth).
 *
 *   php user/themes/maw-starter/bin/maw.php sync              regenerate derived files (run after any block change)
 *   php user/themes/maw-starter/bin/maw.php new-block <type>  scaffold template + blueprint + css, then sync
 *   php user/themes/maw-starter/bin/maw.php lint              check blocks and every page's `blocks:` frontmatter
 *   php user/themes/maw-starter/bin/maw.php normalize         rewrite pages' blocks into the canonical (Admin2) shape
 *   php user/themes/maw-starter/bin/maw.php styleguide        regenerate /styleguide from every block's example
 *
 * Canonical block shape (this is what Admin2 reads and writes):
 *
 *   blocks:
 *     - type: features        # block type
 *       background: alt       # shared section settings: flat on the item
 *       features:             # block content: nested under a key equal to the type
 *         heading: Why us
 *         items: [...]
 *
 * Generated (do not edit by hand):
 *   blueprints/partials/blocks-field.yaml   Admin2 list field (elements per type + shared settings)
 *   blueprints/partials/blocks-field-flex.yaml  same field named `blocks`, for Flex Object blueprints
 *   blueprints/modular/<type>.yaml          modular module blueprints (fields prefixed with header.)
 *   docs/ai/blocks.md                       block catalogue for humans and AI agents (repo root)
 */

declare(strict_types=1);

use Symfony\Component\Yaml\Yaml;

$themeDir = dirname(__DIR__);
$root = dirname($themeDir, 3);
require $root . '/vendor/autoload.php';

const GENERATED = "# GENERATED by bin/maw.php sync from blueprints/blocks/*.yaml. Do not edit by hand.\n";

$cmd = $argv[1] ?? 'help';
exit(match ($cmd) {
    'sync' => sync($themeDir, $root),
    'new-block' => newBlock($themeDir, $root, $argv[2] ?? ''),
    'lint' => lint($themeDir, $root),
    'normalize' => normalize($themeDir, $root),
    'styleguide' => styleguide($themeDir, $root),
    default => help(),
});

function help(): int
{
    fwrite(STDOUT, "Usage: php bin/maw.php sync | new-block <type> | lint | normalize | styleguide\n");
    return 0;
}

/* ---------------------------------------------------------------- schema helpers */

/** @return array<string, array> type => parsed blueprint */
function loadBlocks(string $themeDir): array
{
    $blocks = [];
    foreach (glob($themeDir . '/blueprints/blocks/*.yaml') ?: [] as $file) {
        $type = basename($file, '.yaml');
        if ($type[0] === '_') {
            continue;
        }
        $blocks[$type] = Yaml::parseFile($file) ?: [];
    }
    ksort($blocks);
    return $blocks;
}

/** A block's content fields with form-level and field-level `import@` resolved. */
function blockFields(array $bp, string $themeDir): array
{
    $fields = inlineImports($bp['form']['fields'] ?? [], $themeDir);
    if (isset($bp['form']['import@']['type'])) {
        $fields += importFields($bp['form']['import@']['type'], $themeDir);
    }
    return $fields;
}

function importFields(string $type, string $themeDir): array
{
    $file = $themeDir . '/blueprints/' . $type . '.yaml';
    return is_file($file) ? inlineImports(Yaml::parseFile($file)['form']['fields'] ?? [], $themeDir) : [];
}

function inlineImports(array $fields, string $themeDir): array
{
    $out = [];
    foreach ($fields as $name => $field) {
        if (isset($field['import@']['type'])) {
            $out += importFields($field['import@']['type'], $themeDir);
            continue;
        }
        $out[$name] = $field;
    }
    return $out;
}

/** @return array<string, array> shared settings fields keyed `.name` */
function settingsFields(string $themeDir): array
{
    return importFields('blocks/_settings', $themeDir);
}

/** @return string[] shared setting keys without the dot */
function settingKeys(string $themeDir): array
{
    return array_map(fn ($k) => ltrim((string) $k, '.'), array_keys(settingsFields($themeDir)));
}

/* ---------------------------------------------------------------- sync */

function sync(string $themeDir, string $root): int
{
    $blocks = loadBlocks($themeDir);

    // 1. Admin2 blocks list field
    $options = [];
    $elements = [];
    foreach ($blocks as $type => $bp) {
        $options[$type] = $bp['title'] ?? ucfirst($type);
        $elements[$type] = [
            'type' => 'element',
            'import@' => ['type' => 'blocks/' . $type, 'context' => 'theme://blueprints'],
        ];
    }
    $itemFields = ['.type' => [
        'type' => 'elements',
        'label' => 'Block type',
        'default' => 'rich-text',
        'options' => $options,
        'fields' => $elements,
    ]];
    $itemFields['_settings_heading'] = ['type' => 'spacer', 'title' => 'Section settings'];
    $itemFields += settingsFields($themeDir);
    // No defaults on list-item fields: Admin2 applies them to the list itself when a page is created,
    // producing `blocks: {type: rich-text, ...}` (an object, not a list). Templates and the builder supply defaults.
    foreach ($itemFields as $name => $f) {
        unset($itemFields[$name]['default']);
    }

    $field = ['form' => ['fields' => ['header.blocks' => [
        'type' => 'list',
        'label' => 'Blocks',
        'style' => 'vertical',
        'collapsed' => true,
        'btnLabel' => 'Add block',
        'help' => 'Each item is one page section. Pick a type, fill its fields, drag to reorder.',
        'fields' => $itemFields,
    ]]]];
    writeYaml($themeDir . '/blueprints/partials/blocks-field.yaml', $field);
    // Same field for Flex Object blueprints, where data is stored at the root (`blocks`, not `header.blocks`).
    $flexField = ['form' => ['fields' => ['blocks' => $field['form']['fields']['header.blocks']]]];
    writeYaml($themeDir . '/blueprints/partials/blocks-field-flex.yaml', $flexField);

    // 2. Modular module blueprints (module frontmatter is flat: header.<field>)
    foreach (glob($themeDir . '/blueprints/modular/*.yaml') ?: [] as $old) {
        if (!isset($blocks[basename($old, '.yaml')])) {
            unlink($old);
        }
    }
    foreach ($blocks as $type => $bp) {
        if ($type === 'spacer') {
            continue;
        }
        $settings = prefixFields(settingsFields($themeDir));
        unset($settings['header.hidden']);
        $settings['header.visible'] = ['type' => 'toggle', 'label' => 'Visible', 'default' => 1, 'highlight' => 1,
            'options' => [1 => 'PLUGIN_ADMIN.YES', 0 => 'PLUGIN_ADMIN.NO'], 'validate' => ['type' => 'bool']];
        writeYaml($themeDir . '/blueprints/modular/' . $type . '.yaml', [
            'title' => 'Module: ' . ($bp['title'] ?? $type),
            'extends@' => ['type' => 'default', 'context' => 'system://blueprints/pages'],
            'form' => ['fields' => ['tabs' => ['fields' => [
                'block' => ['type' => 'tab', 'title' => $bp['title'] ?? $type, 'ordering@' => 'content',
                    'fields' => prefixFields(blockFields($bp, $themeDir))],
                'block_settings' => ['type' => 'tab', 'title' => 'Section', 'ordering@' => 'block', 'fields' => $settings],
            ]]]],
        ]);
    }

    // 3. AI / human catalogue
    $md = "<!-- GENERATED by `php user/themes/maw-starter/bin/maw.php sync`. Do not edit by hand. -->\n";
    $md .= "# Block catalogue\n\n";
    $md .= "Blocks are page sections stored as a YAML list under `blocks:` in page frontmatter.\n";
    $md .= "Files per block: `templates/blocks/<type>.html.twig`, `blueprints/blocks/<type>.yaml`, optional `css/blocks/<type>.css`.\n\n";
    $md .= "## Shape (required, this is what Admin2 reads and writes)\n\n";
    $md .= "```yaml\nblocks:\n  - type: features      # block type\n    background: alt     # shared settings: flat on the item\n    features:           # content: nested under a key equal to the type\n      heading: Why us\n      items:\n        - { icon: fa-bolt, title: Fast, text: No database. }\n```\n\n";
    $md .= "If you write content flat by mistake, run `php user/themes/maw-starter/bin/maw.php normalize`.\n\n";
    $md .= "## Shared settings (flat on every block)\n\n| Field | Type / values | Default |\n|---|---|---|\n";
    foreach (settingsFields($themeDir) as $name => $f) {
        $vals = isset($f['options']) ? implode(' \| ', array_map('strval', array_keys($f['options']))) : ($f['type'] ?? '');
        $md .= '| `' . ltrim((string) $name, '.') . '` | ' . $vals . ' | ' . var_export($f['default'] ?? '', true) . " |\n";
    }
    $md .= "\n`buttons` (on blocks that list it) is `[{label, url, style: primary|secondary|ghost, icon, new_tab}]`.\n";
    $md .= "Images are a filename in the page folder, `user://media/...`, `theme://images/...` or a full URL.\n\n";
    $md .= "## Types\n\n" . implode("\n", array_map(fn ($t) => "- [`$t`](#$t): " . ($blocks[$t]['description'] ?? ''), array_keys($blocks))) . "\n";
    foreach ($blocks as $type => $bp) {
        $md .= "\n## $type\n\n" . ($bp['description'] ?? '') . "\n\n**Content fields** (under `$type:`):\n\n";
        foreach (flattenFields(blockFields($bp, $themeDir)) as $line) {
            $md .= $line . "\n";
        }
        if (!empty($bp['example'])) {
            $md .= "\n**Example:**\n\n```yaml\nblocks:\n" . indent(Yaml::dump([canonical($bp['example'], settingKeys($themeDir))], 6, 2), 2) . "```\n";
        }
    }
    @mkdir($root . '/docs/ai', 0775, true);
    file_put_contents($root . '/docs/ai/blocks.md', $md);

    fwrite(STDOUT, sprintf("Synced %d blocks: blocks-field.yaml, modular/*.yaml, docs/ai/blocks.md\n", count($blocks)));
    return 0;
}

/* ---------------------------------------------------------------- shape conversion */

/**
 * Convert a block (flat, nested, or a mix) into the canonical shape.
 * Content in the nested `<type>:` object wins. Flat content keys are moved into it only when the nested
 * object is absent; otherwise they are dropped (they are leftovers from switching the block type in the admin).
 */
function canonical(array $block, array $settingKeys): array
{
    $type = $block['type'] ?? null;
    if (!$type) {
        return $block;
    }
    $out = ['type' => $type];
    $flatContent = [];
    foreach ($block as $key => $value) {
        if ($key === 'type' || $key === $type) {
            continue;
        }
        if (in_array($key, $settingKeys, true)) {
            $out[$key] = $value;
        } else {
            $flatContent[$key] = $value;
        }
    }
    $nested = is_array($block[$type] ?? null) ? $block[$type] : null;
    $out[$type] = $nested ?? $flatContent;
    return $out;
}

function normalize(string $themeDir, string $root): int
{
    $keys = settingKeys($themeDir);
    $changed = 0;
    foreach (pageFiles($root) as $path) {
        $src = (string) file_get_contents($path);
        if (!preg_match('/^---\R(.*?)\R---\R?(.*)$/s', $src, $m)) {
            continue;
        }
        $header = Yaml::parse($m[1]) ?: [];
        $before = $header;
        foreach (['blocks', 'blocks_after'] as $list) {
            if (isset($header[$list]) && (!is_array($header[$list]) || !array_is_list($header[$list]))) {
                // A single object (Admin2 applied item defaults to the list) or a scalar: not recoverable as blocks.
                $header[$list] = [];
            }
            if (!empty($header[$list]) && is_array($header[$list])) {
                $header[$list] = array_map(fn ($b) => is_array($b) ? canonical($b, $keys) : $b, $header[$list]);
            }
        }
        if ($header != $before) {
            file_put_contents($path, "---\n" . Yaml::dump($header, 10, 2) . "---\n" . $m[2]);
            fwrite(STDOUT, 'Normalized ' . substr($path, strlen($root) + 1) . "\n");
            $changed++;
        }
    }
    fwrite(STDOUT, "$changed page(s) changed\n");
    return 0;
}

/* ---------------------------------------------------------------- misc generators */

function prefixFields(array $fields): array
{
    $out = [];
    foreach ($fields as $name => $field) {
        $out[str_starts_with((string) $name, '.') ? 'header' . $name : $name] = $field;
    }
    return $out;
}

function flattenFields(array $fields, string $indent = ''): array
{
    $lines = [];
    foreach ($fields as $name => $f) {
        $type = $f['type'] ?? '?';
        $extra = isset($f['options']) ? ' (' . implode('|', array_map('strval', array_keys($f['options']))) . ')' : '';
        $label = $f['label'] ?? $f['title'] ?? '';
        $lines[] = sprintf('%s- `%s` %s%s: %s', $indent, ltrim((string) $name, '.'), $type, $extra, $label);
        if (!empty($f['fields']) && $type === 'list') {
            $lines = array_merge($lines, flattenFields($f['fields'], $indent . '  '));
        }
    }
    return $lines;
}

function indent(string $text, int $n): string
{
    return (string) preg_replace('/^(?=.)/m', str_repeat(' ', $n), $text);
}

function writeYaml(string $file, array $data): void
{
    @mkdir(dirname($file), 0775, true);
    file_put_contents($file, GENERATED . Yaml::dump($data, 12, 2));
}

/** @return string[] absolute paths of every page .md file */
function pageFiles(string $root): array
{
    $files = [];
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root . '/user/pages', FilesystemIterator::SKIP_DOTS));
    foreach ($it as $file) {
        if ($file->getExtension() === 'md') {
            $files[] = $file->getPathname();
        }
    }
    sort($files);
    return $files;
}

/** Write user/pages/styleguide/blocks.md containing every block's `example` (visual QA page, hidden from nav). */
function styleguide(string $themeDir, string $root): int
{
    $keys = settingKeys($themeDir);
    $blocks = [];
    foreach (loadBlocks($themeDir) as $type => $bp) {
        if (!empty($bp['example'])) {
            $blocks[] = ['type' => 'rich-text', 'spacing' => 'sm', 'background' => 'alt',
                'rich-text' => ['eyebrow' => 'Block', 'heading' => $type, 'text' => $bp['description'] ?? '']];
            $blocks[] = canonical($bp['example'], $keys);
        }
    }
    $header = ['title' => 'Styleguide', 'visible' => false, 'content_position' => 'none',
        'metadata' => ['robots' => 'noindex'], 'blocks' => $blocks];
    $dir = $root . '/user/pages/styleguide';
    @mkdir($dir, 0775, true);
    file_put_contents($dir . '/blocks.md', "---\n# GENERATED by bin/maw.php styleguide\n" . Yaml::dump($header, 10, 2) . "---\n");
    fwrite(STDOUT, 'Wrote user/pages/styleguide/blocks.md with ' . (count($blocks) / 2) . " blocks\n");
    return 0;
}

function newBlock(string $themeDir, string $root, string $type): int
{
    if (!preg_match('/^[a-z][a-z0-9-]*$/', $type)) {
        fwrite(STDERR, "Block type must be kebab-case, e.g. `team-grid`\n");
        return 1;
    }
    $title = ucwords(str_replace('-', ' ', $type));
    $files = [
        "templates/blocks/$type.html.twig" => <<<TWIG
{# $title block. `block` is already flattened: content fields + shared settings. #}
{% embed 'blocks/_section.html.twig' %}
    {% block inner %}
        {% import 'macros/ui.html.twig' as ui %}
        {{ ui.head(block) }}
        <div class="$type">
            {% for item in block.items|default([]) %}
                <div class="{$type}__item">
                    <h3>{{ item.title }}</h3>
                    {% if item.text %}<div>{{ item.text|markdown(false)|raw }}</div>{% endif %}
                </div>
            {% endfor %}
        </div>
        {{ ui.buttons(block.buttons) }}
    {% endblock %}
{% endembed %}

TWIG,
        "blueprints/blocks/$type.yaml" => <<<YAML
title: $title
description: TODO one sentence describing when to use this block.
icon: fa-square
# Example content, written flat for readability (docs and styleguide wrap it in the canonical shape).
example:
  type: $type
  heading: $title
  items:
    - { title: Item one, text: Some text. }
form:
  import@: { type: blocks/_buttons, context: 'theme://blueprints' }
  fields:
    .eyebrow: { type: text, label: Eyebrow }
    .heading: { type: text, label: Heading }
    .intro: { type: textarea, label: Intro (markdown), rows: 2 }
    .items:
      type: list
      label: Items
      style: vertical
      fields:
        .title: { type: text, label: Title }
        .text: { type: textarea, label: Text (markdown), rows: 2 }

YAML,
        "css/blocks/$type.css" => "/* Block: $type - loaded only on pages that use it */\n@layer blocks {\n  .block--$type .$type { display: grid; gap: var(--maw-space-5); }\n}\n",
        "templates/modular/$type.html.twig" => "{# Modular module: $type #}\n{% include 'modular/_block.html.twig' with {type: '$type'} %}\n",
    ];
    foreach ($files as $rel => $content) {
        $path = $themeDir . '/' . $rel;
        if (file_exists($path)) {
            fwrite(STDERR, "Exists, skipped: $rel\n");
            continue;
        }
        @mkdir(dirname($path), 0775, true);
        file_put_contents($path, $content);
        fwrite(STDOUT, "Created $rel\n");
    }
    return sync($themeDir, $root);
}

function lint(string $themeDir, string $root): int
{
    $errors = 0;
    $warnings = 0;
    $blocks = loadBlocks($themeDir);
    $keys = settingKeys($themeDir);

    foreach ($blocks as $type => $bp) {
        if (!is_file("$themeDir/templates/blocks/$type.html.twig")) {
            fwrite(STDOUT, "ERROR block `$type` has a blueprint but no template\n");
            $errors++;
        }
        if (empty($bp['description'])) {
            fwrite(STDOUT, "WARN  block `$type` has no description\n");
            $warnings++;
        }
    }
    foreach (glob("$themeDir/templates/blocks/*.html.twig") ?: [] as $tpl) {
        $type = basename($tpl, '.html.twig');
        if ($type[0] !== '_' && !isset($blocks[$type])) {
            fwrite(STDOUT, "ERROR block `$type` has a template but no blueprint\n");
            $errors++;
        }
    }

    foreach (pageFiles($root) as $path) {
        $rel = substr($path, strlen($root) + 1);
        $src = (string) file_get_contents($path);
        if (!preg_match('/^---\R(.*?)\R---/s', $src, $m)) {
            continue;
        }
        try {
            $header = Yaml::parse($m[1]) ?: [];
        } catch (Throwable $e) {
            fwrite(STDOUT, "ERROR $rel: invalid frontmatter YAML: {$e->getMessage()}\n");
            $errors++;
            continue;
        }
        foreach (['blocks', 'blocks_after'] as $list) {
            if (isset($header[$list]) && (!is_array($header[$list]) || !array_is_list($header[$list]))) {
                fwrite(STDOUT, "ERROR $rel: `$list` must be a list of blocks; run `maw.php normalize`\n");
                $errors++;
                continue;
            }
            foreach ((array) ($header[$list] ?? []) as $i => $block) {
                $type = is_array($block) ? ($block['type'] ?? null) : null;
                // global is provided by the maw-builder plugin (a reference to a synced section), not by the theme.
                if ($type === 'global' && is_dir($root . '/user/plugins/maw-builder')) {
                    continue;
                }
                if (!$type || !isset($blocks[$type])) {
                    fwrite(STDOUT, "ERROR $rel: {$list}[{$i}] unknown type `" . ($type ?? 'none') . "`\n");
                    $errors++;
                    continue;
                }
                if ($block != canonical($block, $keys)) { // == ignores key order
                    fwrite(STDOUT, "WARN  $rel: {$list}[{$i}] ($type) is not in canonical shape; run `maw.php normalize`\n");
                    $warnings++;
                }
            }
        }
    }

    fwrite(STDOUT, $errors ? "$errors error(s), $warnings warning(s)\n" : 'OK: ' . count($blocks) . " blocks, pages valid, $warnings warning(s)\n");
    return $errors ? 1 : 0;
}
